  "items": [
    {
      "title": "BIBB/BAuA Employment Survey 2018 – Personality Traits and Employment (2017–2018)",
      "url_or_doi": "https://doi.org/10.7803/501.18.2.1.10",
      "justification": "The most directly relevant dataset for studying workaholism in Germany during the 2010s. Conducted in 2017–2018, this representative follow-up survey includes 8,010 employed individuals in Germany aged 15 and older. It explicitly measures work addiction (workaholism) using the Dutch Work Addiction Scale (DUWAS), which captures excessive and compulsive working behavior. The dataset also contains personality characteristics and can be linked to employment information from the 2018 BIBB/BAuA Employment Survey. It is particularly suitable for investigating the prevalence, demographic characteristics, occupational differences, and potential predictors of workaholism. A Scientific Use File is available for researchers through the Federal Institute for Vocational Education and Training (BIBB)."
    },
    {
      "title": "BIBB/BAuA Employment Survey – Harmonized Dataset 2006, 2012, and 2018",
      "url_or_doi": "https://doi.org/10.7803/501.061218.1.1.10",
      "justification": "A representative German employment dataset covering three survey waves, including 2012 and 2018. It contains 60,048 observations across the three waves and provides detailed information on working conditions, occupational demands, workload, workplace stress, health, and employment characteristics. Although it does not directly measure workaholism using a dedicated addiction scale, it provides valuable indicators of excessive working behavior and occupational stress. Its longitudinally comparable survey waves make it useful for investigating changes in work intensity and working conditions throughout the 2010s. The dataset is available as a Scientific Use File through BIBB."
    },
    {
      "title": "BAuA Working Time Survey 2017 – Scientific Use File, Version 2",
      "url_or_doi": "https://doi.org/10.48697/baua.azb17.suf.2",
      "justification": "A German working-time survey conducted in 2017 by the Federal Institute for Occupational Safety and Health (BAuA). It provides information on working hours, working-time arrangements, work-related demands, recovery, and employee well-being. Although it does not directly establish workaholism diagnoses, it is relevant for studying behavioral characteristics associated with workaholism, including extended working hours, difficulties separating work from personal life, and insufficient recovery. It is particularly useful for examining relationships between working-time patterns, occupational demands, and health among German employees during the late 2010s."
    },
    {
      "title": "BIBB/BAuA Employment Survey 2018 – Work and Occupation in Transition",
      "url_or_doi": "https://www.bibb.de/de/120401.php",
      "justification": "A large-scale representative survey of approximately 20,000 employed individuals in Germany conducted in 2018. The dataset contains extensive information on employment conditions, occupational requirements, workloads, working environments, and health-related outcomes. Although the main survey does not directly measure workaholism, it provides important contextual variables for investigating excessive work involvement and occupational stress. It is especially valuable because it can be linked to the BIBB follow-up survey on personality traits and work addiction, allowing researchers to examine relationships between workaholism, job characteristics, and working conditions. Scientific Use Files are available through BIBB."
    }
  ]
}
